changeSet.sql:
CREATE INDEX IF NOT EXISTS idx_table_assignment_restaurant_table_id 
ON table_assignment(restaurant_table_id) 
WHERE unassigned_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_table_assignment_waiter_id 
ON table_assignment(waiter_id) 
WHERE unassigned_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_table_assignment_waiter_id_restaurant_table_id 
ON table_assignment(waiter_id, restaurant_table_id) 
WHERE unassigned_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_sessions_table_id 
ON sessions(table_id) 
WHERE expired_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_sessions_table_id_sequence_no_desc 
ON sessions(table_id, sequence_no DESC) 
WHERE expired_at IS NULL;
